(function(){
  // ================== REGLAGES ==================
  const CONFIG = {
    src:            "data:image/png;base64,",

    // ---- REPARTITION (forme / silhouette) ----
    gap:            4,         // pas d'echantillonnage px (grand = plus aere)
    density:        0.62,      // proportion de points gardes (0-1)
    detailBias:     0.25,      // 0 = couverture uniforme (silhouette pleine), 1 = points surtout dans le sombre
    jitter:         0.7,       // desordre du placement (0-1)

    // ---- TONS (ombres / lecture du visage) ----
    dotColor:       "#232323", // couleur des points
    minAlpha:       0.16,      // opacite des zones CLAIRES (peau) - garde la forme
    maxAlpha:       1.0,       // opacite des zones SOMBRES (ombres, lunettes) - fait ressortir
    alphaGamma:     0.75,      // <1 = renforce les demi-ombres (plus de lecture du relief)
    dotSizeMin:     1.5,       // taille des points clairs px
    dotSizeMax:     2.9,       // taille des points sombres px (masse dans les ombres)
    alphaThreshold: 45,        // transparence mini pour placer un point
    brightCutoff:   250,       // ignore le blanc quasi pur (halo detourage)

    // ---- INTERACTION ----
    mouseRadiusRatio: 0.16,    // rayon du cercle creuse (% hauteur affichee)
    repel:          3.4,       // force de repulsion (reactivite)
    spring:         0.05,      // vitesse de retour
    friction:       0.82,      // inertie

    // ---- VIE AU REPOS ----
    idleAmp:        2.4,       // amplitude flottement px (petit = image stable)
    idleSpeed:      0.0011,    // vitesse flottement

    padding:        46,
    assembleOnLoad: true
  };
  // ==============================================

  const stage  = document.getElementById("portrait-stage");
  const canvas = document.createElement("canvas");
  stage.appendChild(canvas);
  const ctx = canvas.getContext("2d");

  // Sprite point (cache) : rond, doux, rapide a blitter
  const SPR = 64;
  const sprite = document.createElement("canvas");
  sprite.width = sprite.height = SPR;
  (function(){
    const s = sprite.getContext("2d");
    const g = s.createRadialGradient(SPR/2, SPR/2, 0, SPR/2, SPR/2, SPR/2);
    g.addColorStop(0.0, CONFIG.dotColor);
    g.addColorStop(0.55, CONFIG.dotColor);
    g.addColorStop(1.0, "rgba(0,0,0,0)");
    s.fillStyle = g; s.beginPath(); s.arc(SPR/2, SPR/2, SPR/2, 0, 6.2832); s.fill();
  })();

  let particles = [];
  let sw = 0, sh = 0, scale = 1, offX = 0, offY = 0, radius = 100, r2 = 1e4;
  let W = 0, H = 0, dpr = 1;
  const mouse = { x: -1e5, y: -1e5 };

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.onload = () => { sample(); layout(); if (CONFIG.assembleOnLoad) scatter(); loop(); };
  img.src = CONFIG.src;

  function sample(){
    sw = img.naturalWidth; sh = img.naturalHeight;
    const off = document.createElement("canvas");
    off.width = sw; off.height = sh;
    const octx = off.getContext("2d");
    octx.drawImage(img, 0, 0);
    const d = octx.getImageData(0, 0, sw, sh).data;
    particles = [];
    const g = CONFIG.gap;
    const dAlpha = CONFIG.maxAlpha - CONFIG.minAlpha;
    const dSize  = CONFIG.dotSizeMax - CONFIG.dotSizeMin;
    for (let y = 0; y < sh; y += g){
      for (let x = 0; x < sw; x += g){
        const i = (y * sw + x) * 4;
        const a = d[i + 3];
        if (a < CONFIG.alphaThreshold) continue;
        const lum = 0.299*d[i] + 0.587*d[i+1] + 0.114*d[i+2];
        if (lum > CONFIG.brightCutoff) continue;
        const dark = 1 - lum / 255;                     // 0 clair .. 1 sombre
        // placement quasi uniforme (silhouette lisible), a peine plus dense dans le sombre
        const keep = CONFIG.density * ((1 - CONFIG.detailBias) + CONFIG.detailBias * dark);
        if (Math.random() > keep) continue;
        // le TON est porte par l'opacite + la taille -> les ombres ressortent
        const shade = Math.pow(dark, CONFIG.alphaGamma);
        const jx = (Math.random() - 0.5) * g * CONFIG.jitter;
        const jy = (Math.random() - 0.5) * g * CONFIG.jitter;
        particles.push({
          hx: x + jx, hy: y + jy, x: 0, y: 0, vx: 0, vy: 0,
          a: CONFIG.minAlpha + dAlpha * shade,
          size: CONFIG.dotSizeMin + dSize * dark,
          phx: Math.random() * 6.2832, phy: Math.random() * 6.2832,
          sx: CONFIG.idleSpeed * (0.6 + Math.random() * 0.9),
          sy: CONFIG.idleSpeed * (0.6 + Math.random() * 0.9)
        });
      }
    }
  }

  function layout(){
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = stage.clientWidth; H = stage.clientHeight;
    canvas.width = W * dpr; canvas.height = H * dpr;
    canvas.style.width = W + "px"; canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const pad = CONFIG.padding;
    scale = Math.min((W - pad*2) / sw, (H - pad*2) / sh);
    offX = (W - sw*scale) / 2; offY = (H - sh*scale) / 2;
    radius = (sh * scale) * CONFIG.mouseRadiusRatio; r2 = radius * radius;
    for (const p of particles){ p.homeX = offX + p.hx * scale; p.homeY = offY + p.hy * scale; }
  }

  function scatter(){ for (const p of particles){ p.x = Math.random()*W; p.y = Math.random()*H; } }

  function loop(){
    window.NOVALEM_PARTICLES_READY = true;
    const t = performance.now();
    ctx.clearRect(0, 0, W, H);
    const rep = CONFIG.repel, spr = CONFIG.spring, fr = CONFIG.friction, amp = CONFIG.idleAmp;
    const mx = mouse.x, my = mouse.y;
    for (let k = 0; k < particles.length; k++){
      const p = particles[k];
      const dx = mx - p.x, dy = my - p.y, d2 = dx*dx + dy*dy;
      if (d2 < r2 && d2 > 0.01){
        const dist = Math.sqrt(d2), f = (radius - dist) / radius, inv = 1 / dist;
        p.vx -= dx * inv * f * rep; p.vy -= dy * inv * f * rep;
      }
      const tx = p.homeX + amp * Math.sin(t * p.sx + p.phx);
      const ty = p.homeY + amp * Math.cos(t * p.sy + p.phy);
      p.vx += (tx - p.x) * spr; p.vy += (ty - p.y) * spr;
      p.vx *= fr; p.vy *= fr; p.x += p.vx; p.y += p.vy;
      const hs = p.size / 2;
      ctx.globalAlpha = p.a;
      ctx.drawImage(sprite, p.x - hs, p.y - hs, p.size, p.size);
    }
    ctx.globalAlpha = 1;
    requestAnimationFrame(loop);
  }

  function move(e){
    const rect = canvas.getBoundingClientRect();
    const pt = e.touches ? e.touches[0] : e;
    mouse.x = pt.clientX - rect.left; mouse.y = pt.clientY - rect.top;
  }
  function leave(){ mouse.x = -1e5; mouse.y = -1e5; }
  canvas.addEventListener("pointermove", move);
  canvas.addEventListener("pointerdown", move);
  canvas.addEventListener("pointerleave", leave);
  canvas.addEventListener("pointerup", leave);
  let rAF; window.addEventListener("resize", () => { cancelAnimationFrame(rAF); rAF = requestAnimationFrame(layout); });
})();
